-- Verified compatibility grants for Programador family.
-- Panel Control: current backend explicitly ensures visual permission for Programador, Programador United and Programador Corellian.
-- Viewer: current backend authorizes through GENERAL_VISOR_USUARIOS_OPERACION.USAR_VISOR and defines company scopes for the same Programador family.
INSERT INTO `rol_permisos` (`id_rol`,`id_subelemento_accion`,`permitido`,`created_by`,`updated_by`)
SELECT r.id_rol, psa.id_subelemento_accion, 1, NULL, NULL
FROM roles r
JOIN perm_subelemento_acciones psa
  ON psa.codigo_permiso IN ('GENERAL_PANEL_DE_CONTROL_ACCESO_VISUAL_MODULO.ACCESO_VISUAL', 'GENERAL_VISOR_USUARIOS_OPERACION.USAR_VISOR')
WHERE r.estado=1 AND r.rol IN ('Programador','Programador United','Programador Corellian')
ON CONFLICT(`id_rol`,`id_subelemento_accion`) DO UPDATE SET
  `permitido`=1,
  `updated_at`=CURRENT_TIMESTAMP,
  `updated_by`=NULL;

PRAGMA user_version = 4;

COMMIT;

PRAGMA foreign_key_check;
